/**
 * Site media (images + videos).
 *
 * Every file lives in Supabase Storage in the public `site-media` bucket.
 * Set VITE_MEDIA_BASE_URL to the bucket's public base URL, e.g.
 *   https://<project>.supabase.co/storage/v1/object/public/site-media
 * and every asset below resolves from your own Supabase project.
 *
 * When the variable is unset the bundled Lovable CDN copies are used, so the
 * site keeps rendering before the media has been imported.
 *
 * Generated by scripts/generate-media-map.ts — do not hand-edit the map.
 */
const base = (import.meta.env?.["VITE_MEDIA_BASE_URL"] as string | undefined)?.replace(/\/$/, "");

