export function assetUrl(filename: string): string {
  if (base) return `${base}/${filename}`;
  return mediaFallback[filename] ?? "";
}

/** Every media filename that must exist in the `site-media` bucket. */
export const mediaFilenames = Object.keys(mediaFallback);
